import{_ as t,o as a,c as i,a3 as n}from"./chunks/framework.Dm8zwdB5.js";const g=JSON.parse('{"title":"Guidelines & Invariants","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/invariants.md","filePath":"integrations/invariants.md","lastUpdated":1789374597000}'),r={name:"integrations/invariants.md"};function s(o,e,l,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="guidelines-invariants" tabindex="-1">Guidelines &amp; Invariants <a class="header-anchor" href="#guidelines-invariants" aria-label="Permalink to &quot;Guidelines &amp; Invariants&quot;">​</a></h1><h2 id="invariants" tabindex="-1">Invariants <a class="header-anchor" href="#invariants" aria-label="Permalink to &quot;Invariants&quot;">​</a></h2><ul><li><strong>Persisted ids are forever</strong> — no rename without a migration.</li><li><strong>Store ids, not names</strong> — display names resolved separately.</li><li><strong>Migrate <code>DomainSavedFilterDataTransformer</code> whenever your domain&#39;s saved-filter schema changes</strong> — it&#39;s what turns a synced saved filter back into your domain&#39;s model; leaving it unmigrated doesn&#39;t fail loudly, it silently buckets the fields it no longer recognizes as unsupported.</li></ul><h2 id="guidelines" tabindex="-1">Guidelines <a class="header-anchor" href="#guidelines" aria-label="Permalink to &quot;Guidelines&quot;">​</a></h2><ul><li><strong>Drive from <code>DomainFiltersModelClient</code>, not <code>DomainFiltersModelStore</code></strong>, whenever a feature writes filters outside the filters presentations — e.g. from a deep link, or an empty state&#39;s &quot;Clear All&quot; button. The <span class="a">Client</span> keeps the change attributed via analytics and picked up by <a href="/unified-filters/site/integrations/responsive-sync-triggering"><code>ResponsiveSyncCoordinator</code></a>.<br>The <span class="a">Store</span> skips both, so the change would go unattributed and unsynced.</li><li><strong>Override <code>DomainFiltersModelStore</code> only when your model blends other reactive sources</strong> — e.g. dynamic types or custom attributes the default store can&#39;t express.</li><li><strong>Override <code>FiltersModelProvider</code> only when filter options are dynamically available</strong> — e.g. deriving option lists from live filtered data instead of the default read of the store.</li><li><strong>Override <code>DomainFiltersModelUpdater</code> only when you must preserve non-filter fields or make filters depend on each other</strong> — e.g. sort/search/template state, or one filter&#39;s selection affecting another filter&#39;s options.</li></ul>',5)])])}const m=t(r,[["render",s]]);export{g as __pageData,m as default};
